class EditorTest : public EditingTestBase {
 public:
  void TearDown() override {
    GetDocument().GetFrame()->GetSystemClipboard()->WritePlainText(String(""));
    GetDocument().GetFrame()->GetSystemClipboard()->CommitWrite();
    EditingTestBase::TearDown();
  }

  Editor& GetEditor() const { return GetDocument().GetFrame()->GetEditor(); }

  void ExecuteCopy() {
    Editor& editor = GetDocument().GetFrame()->GetEditor();
    editor.CreateCommand("Copy").Execute();
    test::RunPendingTasks();
  }

  WebInputEventResult SendPrimaryModifierShortcut(int windows_key_code,
                                                  char character) {
#if BUILDFLAG(IS_MAC)
    constexpr WebInputEvent::Modifiers kPrimaryModifier =
        WebInputEvent::kMetaKey;
#else
    constexpr WebInputEvent::Modifiers kPrimaryModifier =
        WebInputEvent::kControlKey;
#endif
    WebKeyboardEvent event(WebInputEvent::Type::kRawKeyDown, kPrimaryModifier,
                           WebInputEvent::GetStaticTimeStampForTests());
    event.windows_key_code = windows_key_code;
    event.dom_key = ui::DomKey::FromCharacter(character);
    return GetDocument().GetFrame()->GetEventHandler().KeyEvent(event);
  }

  ptrdiff_t SizeOfRedoStack() const {
    return std::distance(GetEditor().GetUndoStack().RedoSteps().begin(),
                         GetEditor().GetUndoStack().RedoSteps().end());
  }

  ptrdiff_t SizeOfUndoStack() const {
    return std::distance(GetEditor().GetUndoStack().UndoSteps().begin(),
                         GetEditor().GetUndoStack().UndoSteps().end());
  }
};

TEST_F(EditorTest, CanCopyCrossingShadowBoundary) {
  const SelectionInDomTree selection = SetSelectionTextToBody(
      "<p><template data-mode=open>^abc</template></p><b>|</b>");
  Selection().SetSelection(selection, SetSelectionOptions());
  EXPECT_TRUE(GetDocument().GetFrame()->GetEditor().CanCopy());
}

TEST_F(EditorTest, copyGeneratedPassword) {
  // Checks that if the password field has the value generated by Chrome
  // (HTMLInputElement::shouldRevealPassword will be true), copying the field
  // should be available.
  const char* body_content = "<input type='password' id='password'></input>";
  SetBodyContent(body_content);

  auto& element = To<HTMLInputElement>(
      *GetDocument().getElementById(AtomicString("password")));

  const String kPasswordValue = "secret";
  element.Focus();
  element.SetValue(kPasswordValue);
  element.SetSelectionRange(0, kPasswordValue.length());

  Editor& editor = GetDocument().GetFrame()->GetEditor();
  EXPECT_FALSE(editor.CanCopy());

  element.SetShouldRevealPassword(true);
  EXPECT_TRUE(editor.CanCopy());
}

TEST_F(EditorTest, CopyVisibleSelection) {
  const char* body_content = "<input id=hiding value=HEY>";
  SetBodyContent(body_content);

  auto& text_control = To<HTMLInputElement>(
      *GetDocument().getElementById(AtomicString("hiding")));
  text_control.select();

  ExecuteCopy();

  const String copied =
      GetDocument().GetFrame()->GetSystemClipboard()->ReadPlainText();
  EXPECT_EQ("HEY", copied);
}

TEST_F(EditorTest, HardenedCopyCannotBeCanceledOrOverwrittenByPage) {
  ScopedHardenedPrivacyModeForTest hardened_privacy_mode(true);
  GetDocument().GetSettings()->SetScriptEnabled(true);

  const SelectionInDomTree selection = SetSelectionTextToBody(
      "<p>^copy this text|</p><span id=decoy>decoy</span>");
  Selection().SetSelection(selection, SetSelectionOptions());

  Element* script = GetDocument().CreateRawElement(html_names::kScriptTag);
  script->SetInnerHTMLWithoutTrustedTypes(R"JS(
    document.addEventListener('copy', event => {
      document.body.setAttribute('data-copy-seen', 'yes');
      event.clipboardData.setData('text/plain', 'blocked');
      event.preventDefault();
    });
    document.addEventListener('keydown', event => {
      document.body.setAttribute('data-key-seen', 'yes');
      event.preventDefault();
      const range = document.createRange();
      range.selectNodeContents(document.getElementById('decoy'));
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
      document.body.setAttribute(
          'data-dom-copy-result', document.execCommand('copy'));
    });
  )JS");
  GetDocument().body()->AppendChild(script);

#if BUILDFLAG(IS_MAC)
  constexpr WebInputEvent::Modifiers kCopyModifier = WebInputEvent::kMetaKey;
#else
  constexpr WebInputEvent::Modifiers kCopyModifier =
      WebInputEvent::kControlKey;
#endif
  WebKeyboardEvent copy_event(WebInputEvent::Type::kRawKeyDown, kCopyModifier,
                              WebInputEvent::GetStaticTimeStampForTests());
  copy_event.windows_key_code = VKEY_C;
  copy_event.dom_key = ui::DomKey::FromCharacter('c');

  EXPECT_EQ(WebInputEventResult::kHandledSystem,
            GetDocument().GetFrame()->GetEventHandler().KeyEvent(copy_event));
  test::RunPendingTasks();

  EXPECT_EQ("copy this text", GetDocument()
                                  .GetFrame()
                                  ->GetSystemClipboard()
                                  ->ReadPlainText());
  EXPECT_EQ("yes", GetDocument().body()->getAttribute(
                       AtomicString("data-key-seen")));
  EXPECT_EQ("yes", GetDocument().body()->getAttribute(
                       AtomicString("data-copy-seen")));
  EXPECT_EQ("true", GetDocument().body()->getAttribute(
                        AtomicString("data-dom-copy-result")));
}

