TEST_F(EditorTest, HardenedCutCannotBeCanceledOrReplaceClipboard) {
  ScopedHardenedPrivacyModeForTest hardened_privacy_mode(true);
  GetDocument().GetSettings()->SetScriptEnabled(true);
  SetBodyContent("<input id=target value='cut this'>");
  auto& target = To<HTMLInputElement>(*GetElementById("target"));
  target.Focus();
  target.SetSelectionRange(0, 8);

  Element* script = GetDocument().CreateRawElement(html_names::kScriptTag);
  script->SetInnerHTMLWithoutTrustedTypes(R"JS(
    target.addEventListener('beforeinput', event => {
      document.body.dataset.beforeinputCanceled = event.inputType;
      event.preventDefault();
    });
    target.addEventListener('cut', event => {
      document.body.dataset.cutCanceled = 'yes';
      event.clipboardData.setData('text/plain', 'page replacement');
      event.preventDefault();
    });
  )JS");
  GetDocument().body()->AppendChild(script);

  EXPECT_EQ(WebInputEventResult::kHandledSystem,
            SendPrimaryModifierShortcut(VKEY_X, 'x'));
  test::RunPendingTasks();

  EXPECT_EQ("", target.Value());
  EXPECT_EQ("cut this", GetDocument()
                            .GetFrame()
                            ->GetSystemClipboard()
                            ->ReadPlainText());
  EXPECT_EQ("deleteByCut", GetDocument().body()->getAttribute(
                               AtomicString("data-beforeinput-canceled")));
  EXPECT_EQ("yes", GetDocument().body()->getAttribute(
                          AtomicString("data-cut-canceled")));
}

TEST_F(EditorTest, HardenedPasteCannotBeCanceled) {
  ScopedHardenedPrivacyModeForTest hardened_privacy_mode(true);
  GetDocument().GetSettings()->SetScriptEnabled(true);
  SetBodyContent("<input id=target value='replace me'>");
  auto& target = To<HTMLInputElement>(*GetElementById("target"));
  target.Focus();
  target.SetSelectionRange(0, 10);
  GetDocument().GetFrame()->GetSystemClipboard()->WritePlainText("pasted");
  GetDocument().GetFrame()->GetSystemClipboard()->CommitWrite();
  test::RunPendingTasks();
  ASSERT_EQ("pasted", GetDocument()
                          .GetFrame()
                          ->GetSystemClipboard()
                          ->ReadPlainText());

  Element* script = GetDocument().CreateRawElement(html_names::kScriptTag);
  script->SetInnerHTMLWithoutTrustedTypes(R"JS(
    target.addEventListener('beforeinput', event => {
      document.body.dataset.beforeinputCanceled = event.inputType;
      event.preventDefault();
    });
    target.addEventListener('textInput', event => {
      document.body.dataset.textinputCanceled = 'yes';
      event.preventDefault();
    });
    target.addEventListener('paste', event => {
      document.body.dataset.pasteCanceled = event.clipboardData.getData('text/plain');
      event.preventDefault();
    });
  )JS");
  GetDocument().body()->AppendChild(script);

  EXPECT_EQ(WebInputEventResult::kHandledSystem,
            SendPrimaryModifierShortcut(VKEY_V, 'v'));
  test::RunPendingTasks();

  EXPECT_EQ("pasted", target.Value());
  EXPECT_EQ("pasted", GetDocument()
                          .GetFrame()
                          ->GetSystemClipboard()
                          ->ReadPlainText());
  EXPECT_EQ("insertFromPaste", GetDocument().body()->getAttribute(
                                  AtomicString("data-beforeinput-canceled")));
  EXPECT_EQ("yes", GetDocument().body()->getAttribute(
                          AtomicString("data-textinput-canceled")));
  EXPECT_EQ("pasted", GetDocument().body()->getAttribute(
                             AtomicString("data-paste-canceled")));
}

TEST_F(EditorTest, HardenedSelectAllCannotBeCanceledByKeydown) {
  ScopedHardenedPrivacyModeForTest hardened_privacy_mode(true);
  GetDocument().GetSettings()->SetScriptEnabled(true);
  SetBodyContent("<input id=target value='select all'>");
  auto& target = To<HTMLInputElement>(*GetElementById("target"));
  target.Focus();
  target.SetSelectionRange(3, 3);

  Element* script = GetDocument().CreateRawElement(html_names::kScriptTag);
  script->SetInnerHTMLWithoutTrustedTypes(R"JS(
    target.addEventListener('keydown', event => {
      document.body.dataset.keyCanceled = 'yes';
      event.preventDefault();
    });
  )JS");
  GetDocument().body()->AppendChild(script);

  EXPECT_EQ(WebInputEventResult::kHandledSystem,
            SendPrimaryModifierShortcut(VKEY_A, 'a'));
  EXPECT_EQ(0u, target.selectionStart());
  EXPECT_EQ(10u, target.selectionEnd());
  EXPECT_EQ("yes", GetDocument().body()->getAttribute(
                          AtomicString("data-key-canceled")));
}

TEST_F(EditorTest, DontCopyHiddenSelections) {
  const char* body_content =
      "<input type=checkbox id=checkbox>"
      "<input id=hiding value=HEY>";
  SetBodyContent(body_content);

  auto& text_control = To<HTMLInputElement>(
      *GetDocument().getElementById(AtomicString("hiding")));
  text_control.select();

  auto& checkbox = To<HTMLInputElement>(
      *GetDocument().getElementById(AtomicString("checkbox")));
  checkbox.Focus();

  ExecuteCopy();

  const String copied =
      GetDocument().GetFrame()->GetSystemClipboard()->ReadPlainText();
  EXPECT_TRUE(copied.empty()) << copied << " was copied.";
}

TEST_F(EditorTest, ReplaceSelection) {
  const char* body_content = "<input id=text value='HELLO'>";
  SetBodyContent(body_content);

  auto& text_control =
      To<HTMLInputElement>(*GetDocument().getElementById(AtomicString("text")));
  text_control.select();
  text_control.SetSelectionRange(2, 2);

  Editor& editor = GetDocument().GetFrame()->GetEditor();
  editor.ReplaceSelection("NEW");

  EXPECT_EQ("HENEWLLO", text_control.Value());
}

// http://crbug.com/263819
TEST_F(EditorTest, RedoWithDisconnectedEditable) {
  SetBodyContent("<p contenteditable id=target></p>");
  auto& target = *GetElementById("target");
  target.Focus();
  GetDocument().execCommand("insertHtml", false, "<b>xyz</b>",
                            ASSERT_NO_EXCEPTION);
  ASSERT_EQ("<b>xyz</b>", target.GetInnerHTMLString());
  ASSERT_EQ(0, SizeOfRedoStack());
  ASSERT_EQ(1, SizeOfUndoStack());

  GetEditor().Undo();
  ASSERT_EQ(1, SizeOfRedoStack());
  ASSERT_EQ(0, SizeOfUndoStack());

  target.remove();
  EXPECT_EQ(0, SizeOfRedoStack())
      << "We don't need to have redo steps for removed <input>";
  EXPECT_EQ(0, SizeOfUndoStack());
}

